/* ===== src/js/72-filmstrip.js ===== */
/* ==========================================================================
   SG.filmstrip: mirror the chosen thumbnail into the stage
   --------------------------------------------------------------------------
   The thumbnails are native radio buttons, so the browser already does the hard part: one tab stop,
   arrow keys that move AND choose (wrapping), a form value. This script only makes the big picture
   follow the choice. Without it the strip still works as a radio group; the stage just stays put.

     <fieldset class="filmstrip__strip" aria-controls="trail-stage"> … </fieldset>
     <label class="filmstrip__thumb" [data-tone="3"]>   (a swatch: the label paints its own tone)
       <input type="radio" name="trail" data-full="harbour.svg" data-alt="Three boats under a low sun"
              data-title="Harbour at dawn" data-label="Mar 29" data-meta="Low sun, flat water.">
       <img src="harbour.svg" alt="Harbour at dawn">

   aria-controls on the strip names the stage (a .media figure). On change:
     data-full    the stage <img> src (and srcset is dropped); SG.media then shows its loading state
     data-alt     the stage <img> alt: describe the PICTURE here, the thumbnail's own alt names the CHOICE
     data-title / data-label / data-meta   fill .media__title / .media__label / .media__meta if present
     data-stage-tone   "1"…"6" | "ink" | "none": sets (or clears) data-tone on the stage, so a swatch choice
                  recolours the space behind a cut-out picture
   and the change is announced ("Showing Harbour at dawn, 2 of 6") because the picture that changed is
   not where focus is. Home / End jump to the first / last thumbnail (the browser gives the arrows).

   A STRIP THAT SCROLLS SAYS SO. A thumbnail cut at the edge is the only sign that there is more, so it must
   be cut, not whole (a strip that ends on a whole thumbnail, with five more hidden, looks finished):
     · peek     the gap between thumbnails (from 8px; 12 by default), and only if no gap can do it the size
                of the thumbnails (by at most an eighth), is chosen so that, at rest, the first thumbnail that
                does not fit shows 40 to 70% of itself (it is cut by 30 to 60%). Measured, and again on every
                resize. Written to the track as --_strip-gap and --_thumb-k.
     · reveal   on load, and after every choice, the track scrolls (sideways only, never the page) so the
                chosen thumbnail is whole AND each side with more to show cuts a neighbour part way, never at
                a gap. Smooth unless motion is reduced. (There are no snap points: a snap would pull this
                position back to the nearest thumbnail edge.)
   ========================================================================== */
(function (SG) {
  'use strict';

  function stripOf(el) { return el.closest ? el.closest('.filmstrip__strip') : null; }
  function radios(strip) { return SG.qsa('.filmstrip__thumb > input[type="radio"]', strip); }

  function setText(stage, cls, value) {
    var el = stage.querySelector('.' + cls);
    if (el && value != null) el.textContent = value;
  }

  function show(input) {
    var strip = stripOf(input);
    var stage = strip && document.getElementById(strip.getAttribute('aria-controls') || '');
    if (!stage) return;
    var thumb = input.closest('.filmstrip__thumb');
    var img = stage.querySelector('.media__frame img');
    var full = input.getAttribute('data-full');
    var alt = input.getAttribute('data-alt');

    if (img && full && img.getAttribute('src') !== full) {
      img.removeAttribute('srcset');
      img.setAttribute('src', full);
      if (SG.media) SG.media.watch(img);
    }
    if (img && alt != null) img.setAttribute('alt', alt);

    var tone = input.getAttribute('data-stage-tone');
    if (tone != null) {
      if (tone && tone !== 'none') stage.setAttribute('data-tone', tone); else stage.removeAttribute('data-tone');
    }

    var title = input.getAttribute('data-title');
    setText(stage, 'media__title', title);
    setText(stage, 'media__label', input.getAttribute('data-label'));
    setText(stage, 'media__meta', input.getAttribute('data-meta'));

    var all = radios(strip);
    var name = title || alt || (thumb && thumb.textContent.replace(/\s+/g, ' ').trim()) || '';
    SG.announce('Showing ' + name + ', ' + (all.indexOf(input) + 1) + ' of ' + all.length);
  }

  document.addEventListener('change', function (e) {
    var t = e.target;
    if (t && t.matches && t.matches('.filmstrip__thumb > input[type="radio"]') && t.checked) show(t);
  });

  document.addEventListener('keydown', function (e) {
    var t = e.target;
    if (!t || !t.matches || !t.matches('.filmstrip__thumb > input[type="radio"]')) return;
    if (e.key !== 'Home' && e.key !== 'End') return;
    var list = radios(stripOf(t)).filter(function (r) { return !r.disabled; });
    var to = e.key === 'Home' ? list[0] : list[list.length - 1];
    if (!to) return;
    e.preventDefault();
    to.checked = true;
    to.focus();
    to.dispatchEvent(new Event('change', { bubbles: true }));
  });

  // ---- measuring: positions along the track from its start edge (left, or right in RTL), scroll included ----
  function geometry(track) {
    var cs = getComputedStyle(track);
    var rtl = cs.direction === 'rtl';
    var tr = track.getBoundingClientRect();
    var scrolled = Math.abs(track.scrollLeft);
    var edge = rtl ? tr.right - track.clientLeft : tr.left + track.clientLeft;
    var thumbs = SG.qsa('.filmstrip__thumb', track).map(function (el) {
      var r = el.getBoundingClientRect();
      var start = (rtl ? edge - r.right : r.left - edge) + scrolled;
      return { el: el, start: start, end: start + r.width };
    });
    return {
      rtl: rtl, thumbs: thumbs, cw: track.clientWidth, max: Math.max(0, track.scrollWidth - track.clientWidth),
      pad: parseFloat(rtl ? cs.paddingRight : cs.paddingLeft) || 0,
      room: parseFloat(rtl ? cs.scrollPaddingRight : cs.scrollPaddingLeft) || 0
    };
  }

  /** How well an edge at x cuts a thumbnail: 0 when it falls in a gap or on a thumbnail's own edge, 0.5 when it
      cuts one in half. */
  function cut(thumbs, x) {
    for (var i = 0; i < thumbs.length; i++) {
      var t = thumbs[i];
      if (x > t.start && x < t.end) { var f = (x - t.start) / (t.end - t.start); return Math.min(f, 1 - f); }
    }
    return 0;
  }

  /** The gap (and if that is not enough, the size) that makes the first thumbnail past the edge show 40 to 70% of
      itself at rest. A gap change is preferred: thumbnails keep their size unless no gap from 8px (to 16px, or
      22% of a big thumbnail) can do it (72px thumbnails in a 256px track end on a whole one at every such
      gap), and then they change by as little as they must, at most an eighth. */
  function peek(track) {
    track.style.removeProperty('--_strip-gap');
    track.style.removeProperty('--_thumb-k');
    var g = geometry(track);
    if (g.thumbs.length < 2 || !g.max) return; // everything fits: nothing to hint at
    var t0 = g.thumbs[0].end - g.thumbs[0].start;
    var gap0 = g.thumbs[1].start - g.thumbs[0].end;
    var x = g.cw - g.pad; // the run from the first thumbnail to the far edge
    var pick = null, fallback = { miss: Infinity };
    var most = Math.max(16, Math.round(t0 * 0.22)); // a big thumbnail may stand further apart (96px: up to 21px)
    for (var gi = 16; gi <= 2 * most; gi++) { // gaps from 8px, in half pixels
      var gap = gi / 2;
      for (var ki = -12; ki <= 12; ki++) { // sizes within an eighth, in 1% steps
        var k = 1 + ki / 100, t = t0 * k;
        var v = x % (t + gap); // what the last pitch shows: part of a thumbnail (v < t), or a whole one and part of a gap
        var shown = v < t ? v / t : 0;
        // a 1% size change costs as much as a 2px gap change; between near equals, a cut nearer the middle wins
        var cost = Math.abs(gap - gap0) / 8 + Math.abs(ki) / 4 + Math.abs(shown - 0.55) * 2;
        // cut by 30 to 60%: 40 to 70% of it shows (a bit more than half is the easier one to recognise)
        if (shown >= 0.4 && shown <= 0.7 && (!pick || cost < pick.cost)) pick = { gap: gap, k: k, cost: cost };
        var miss = Math.abs(shown - 0.55);
        if (miss < fallback.miss) fallback = { gap: gap, k: k, miss: miss };
      }
    }
    pick = pick || fallback;
    if (Math.abs(pick.gap - gap0) > 0.01) track.style.setProperty('--_strip-gap', pick.gap + 'px');
    if (Math.abs(pick.k - 1) > 0.001) track.style.setProperty('--_thumb-k', String(pick.k));
  }

  /** Scroll the track (sideways only, never the page) so the chosen thumbnail is whole, with room for its ring,
      and each side that has more to show cuts a neighbour part way. */
  function reveal(track, smooth) {
    var on = track.querySelector('.filmstrip__thumb > input:checked');
    if (!on) return;
    var g = geometry(track);
    if (!g.max) return;
    var c = null;
    g.thumbs.forEach(function (t) { if (t.el === on.parentNode) c = t; });
    if (!c) return;
    var room = Math.max(g.room, g.pad);
    var lo = Math.max(0, c.end + room - g.cw), hi = Math.min(g.max, c.start - room);
    if (lo > hi) { lo = hi = Math.max(0, Math.min(g.max, c.start - room)); }
    var now = Math.abs(track.scrollLeft);
    // an edge at the strip's own end needs no cue; any other edge should cut a thumbnail
    function quality(s) {
      var ql = s <= 0.5 ? 0.5 : cut(g.thumbs, s);
      var qr = s >= g.max - 0.5 ? 0.5 : cut(g.thumbs, s + g.cw);
      return Math.min(ql, qr);
    }
    // stay put if the chosen one is already whole and both edges already read as more (or as the end)
    if (now >= lo - 0.5 && now <= hi + 0.5 && quality(now) >= 0.2) return;
    var best = now, bestQ = -1, centre = (c.start + c.end) / 2;
    for (var s = Math.floor(lo); s <= Math.ceil(hi); s++) {
      var x = Math.max(lo, Math.min(hi, s));
      // the better cut first; between equal cuts, the position that keeps the chosen one nearer the middle
      var q = Math.round(Math.min(quality(x), 0.3) * 100) - Math.abs(centre - (x + g.cw / 2)) / g.cw;
      if (q > bestQ) { bestQ = q; best = x; }
    }
    var left = g.rtl ? -best : best;
    if (smooth && track.scrollTo) track.scrollTo({ left: left, behavior: SG.motion && SG.motion.reduced() ? 'auto' : 'smooth' });
    else track.scrollLeft = left;
  }

  function settle(track) { peek(track); reveal(track, false); }

  // after a choice the stage changes; the strip brings the choice and its neighbours into view
  document.addEventListener('change', function (e) {
    var t = e.target;
    var track = t && t.closest && t.closest('.filmstrip__track');
    if (track && t.matches('.filmstrip__thumb > input[type="radio"]') && t.checked) reveal(track, true);
  });

  SG.filmstrip = { show: show, reveal: reveal, peek: peek };
  SG.ready(function () {
    var tracks = SG.qsa('.filmstrip__track');
    tracks.forEach(settle);
    // the gap depends on the track's width (a rotation, the page's layout at another text size)
    if ('ResizeObserver' in window) {
      var widths = new WeakMap();
      var ro = new ResizeObserver(function (entries) {
        entries.forEach(function (en) {
          var w = Math.round(en.contentRect.width);
          if (widths.get(en.target) === w) return;
          widths.set(en.target, w);
          settle(en.target);
        });
      });
      tracks.forEach(function (tr) { ro.observe(tr); });
    }
  });
})((window.SG = window.SG || {}));
